import type { Biology30LessonContent } from "./content-types.js";

type RawSection = [label: string, title: string, mechanism: string, evidence: string];
type RawCase = [id: string, label: string, evidence: string, explanation: string];
type RawMap = [title: string, description: string, first: [string, string], second: [string, string], third: [string, string]];
type RawLab = [title: string, intro: string, prompt: string, first: RawCase, second: RawCase, third: RawCase, fallback: string];
type RawPractice = [prompt: string, correct: string, wrong1: string, wrong2: string, wrong3: string, rationale: string];
type CSeed = {
  id: string;
  learning: string;
  success: [string, string, string];
  warmup: [string, string, string];
  sections: [RawSection, RawSection, RawSection, RawSection];
  map: RawMap;
  lab: RawLab;
  anchor: RawPractice;
  bounded: RawPractice;
  artifact: [string, string, string, string];
  exit: [string, string, string];
  terms: string[];
  materials?: string;
  safety?: string;
};

