function makeC(seed: CSeed): Biology30LessonContent {
  const lessonContext = C_LESSON_CONTEXT[seed.id];
  if (!lessonContext) {
    throw new Error(`Missing Unit C materials and safety context for ${seed.id}.`);
  }
  const [mapTitle, mapDescription, ...mapNodes] = seed.map;
  const [labTitle, labIntro, labPrompt, ...labTail] = seed.lab;
  const fallback = labTail.at(-1) as string;
  const rawCases = labTail.slice(0, 3) as RawCase[];
  const [anchorPrompt, anchorCorrect, ...anchorTail] = seed.anchor;
  const [boundedPrompt, boundedCorrect, ...boundedTail] = seed.bounded;
  const spec: Biology30CompactLessonSpec = {
    id: seed.id,
    unitCode: "C",
    learningIntention: seed.learning,
    successCriteria: seed.success,
    materials: seed.materials ?? lessonContext.materials,
    safety: seed.safety ?? lessonContext.safety,
    warmup: { title: seed.warmup[0], prompt: seed.warmup[1], placeholder: seed.warmup[2] },
    sections: seed.sections.map(([label, title, mechanism, evidence]) => ({ label, title, mechanism, evidence })) as Biology30CompactLessonSpec["sections"],
    conceptMap: { title: mapTitle, description: mapDescription, nodes: mapNodes.map(([label, detail]) => ({ label, detail })) },
    interaction: {
      title: labTitle,
      intro: labIntro,
      prompt: labPrompt,
      cases: rawCases.map(([id, label, evidence, explanation]) => ({ id, label, evidence, explanation })) as Biology30CompactLessonSpec["interaction"]["cases"],
      staticFallback: fallback
    },
    practice: {
      anchorPrompt,
      anchorCorrect,
      misconceptions: anchorTail.slice(0, 3) as [string, string, string],
      anchorRationale: anchorTail[3],
      boundedPrompt,
      boundedCorrect,
      overclaims: boundedTail.slice(0, 3) as [string, string, string],
      boundedRationale: boundedTail[3]
    },
    artifact: { prompt: seed.artifact[0], evidenceRequirements: seed.artifact.slice(1) as [string, string, string] },
    exit: { title: seed.exit[0], prompt: seed.exit[1], placeholder: seed.exit[2] },
    glossaryTerms: seed.terms,
    sourceSummary: C_SOURCE
  };
  return buildBiology30CompactLesson(spec);
}

